    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate required fields
  if (typeof args !== 'object' || args === null) {
    throw new Error('Arguments must be an object');
  }

  if (!('order_id' in args) || typeof args.order_id !== 'string') {
    throw new Error('Missing or invalid required field: order_id');
  }

  // Reject extra fields
  const allowed = ['order_id', 'include_history'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  // Validate include_history type if provided
  if ('include_history' in args && typeof args.include_history !== 'boolean') {
    throw new Error('include_history must be a boolean');
